import type { PopoverProps, PopoverTriggerProps, PopoverContentProps } from "./popover.types";

import React, { cloneElement, forwardRef, useCallback } from "react";
import { clsx } from "clsx";
import { useTheme } from "@theme";
import { FloatingArrow, type ReferenceType } from "@floating-ui/react";
import { Button, type ButtonProps } from "@components/button";
import { Divider, DividerProps } from "@components/divider";

import { PopoverClasses, StyledPopover } from "./popover.styles";
import {
  usePopover,
  type UsePopoverOptions,
  PopoverContext,
  usePopoverContext,
} from "./hooks/use-popover";

const PopoverRoot: React.FC<PopoverProps> = ({
  children,
  arrow = true,
  position = "top",
  open: controlledOpen,
  onOpenChange,
  offset = 8,
  variant = "default",
  styleSlots,
  dismissable = false,
}) => {
  const hookOptions: UsePopoverOptions = {
    position,
    open: controlledOpen,
    dismissable,
    onOpenChange,
    arrow,
    variant,
    offset,
    styleSlots,
  };

  const contextValue = usePopover(hookOptions);

  return <PopoverContext.Provider value={contextValue}>{children}</PopoverContext.Provider>;
};
PopoverRoot.displayName = "Popover";

const Trigger = forwardRef<ReferenceType, PopoverTriggerProps>(
  ({ children, className, ...triggerProps }, forwardedRef) => {
    const theme = useTheme();
    const {
      getReferenceProps,
      refs,
      currentOpenState,
      styleSlots: contextStyleSlots,
      variant,
    } = usePopoverContext();

    const childrenArray = React.Children.toArray(children);
    if (childrenArray.length !== 1 || !React.isValidElement(childrenArray[0])) {
      throw new Error("Popover.Trigger requires a single valid React element as its child.");
    }
    const childElement = childrenArray[0] as React.ReactElement;

    const setRef = useCallback(
      (node: ReferenceType | null) => {
        refs.setReference(node);
        if (typeof forwardedRef === "function") {
          forwardedRef(node);
        } else if (forwardedRef) {
          (forwardedRef as React.MutableRefObject<ReferenceType | null>).current = node;
        }
      },
      [refs, forwardedRef],
    );

    const referenceProps = getReferenceProps({
      ref: setRef,
      disabled: triggerProps.disabled,
    });

    // Move ARIA from wrapper to the actual trigger element for better a11y semantics
    const ariaDescribedBy = referenceProps["aria-describedby"];
    const ariaHasPopup = referenceProps["aria-haspopup"];
    const ariaControls = referenceProps["aria-controls"];

    referenceProps["aria-describedby"] = undefined;
    referenceProps["aria-haspopup"] = undefined;
    referenceProps["aria-controls"] = undefined;

    return (
      <StyledPopover
        className={PopoverClasses.triggerWrapper}
        currentTheme={theme}
        styleSlots={contextStyleSlots}
        variant={variant}
        {...referenceProps}
      >
        {cloneElement(childElement, {
          ...childElement.props,
          className: clsx(childElement.props.className, className),
          "data-popover-open": currentOpenState ? "true" : "false",
          ["aria-describedby"]: ariaDescribedBy || undefined,
          ["aria-haspopup"]: ariaHasPopup,
          ["aria-controls"]: ariaControls,
          ...triggerProps,
        })}
      </StyledPopover>
    );
  },
);
Trigger.displayName = "Popover.Trigger";

const Content = forwardRef<HTMLDivElement, PopoverContentProps>(
  ({ children, className, style, ...contentProps }, forwardedRef) => {
    const {
      refs,
      floatingStyles,
      floatingContext,
      getFloatingProps,
      isMounted,
      showArrow,
      arrowRef,
      actualPlacement,
      styles,
      variant,
      styleSlots: contextStyleSlots,
    } = usePopoverContext();
    const theme = useTheme();

    if (!isMounted) return null;

    return (
      <div
        ref={refs.setFloating}
        style={{ zIndex: theme?.zIndex?.dynamic, ...floatingStyles, ...styles, ...(style || {}) }}
        {...getFloatingProps(contentProps)}
      >
        <StyledPopover
          ref={forwardedRef}
          className={clsx(PopoverClasses.root, className)}
          currentTheme={theme}
          styleSlots={contextStyleSlots}
          variant={variant}
        >
          {showArrow && (
            <FloatingArrow
              ref={arrowRef}
              className={clsx(PopoverClasses.arrow, {
                [PopoverClasses.arrowTop]: actualPlacement?.includes("top"),
                [PopoverClasses.arrowBottom]: actualPlacement?.includes("bottom"),
                [PopoverClasses.arrowLeft]: actualPlacement?.includes("left"),
                [PopoverClasses.arrowRight]: actualPlacement?.includes("right"),
              })}
              context={floatingContext}
              data-testid="arrow"
            />
          )}
          <div className={PopoverClasses.content}>{children}</div>
        </StyledPopover>
      </div>
    );
  },
);
Content.displayName = "Popover.Content";

const PopoverDivider = forwardRef<HTMLDivElement, DividerProps>(
  ({ children, className, ...props }, forwardedRef) => (
    <Divider ref={forwardedRef} className={clsx(PopoverClasses.divider, className)} {...props}>
      {children}
    </Divider>
  ),
);
PopoverDivider.displayName = "Popover.Divider";

const FooterButton = forwardRef<HTMLButtonElement, ButtonProps>(
  ({ children, className, ...props }, forwardedRef) => (
    <Button
      ref={forwardedRef}
      buttonType="tertiary"
      className={clsx(PopoverClasses.footerButton, className)}
      {...props}
    >
      {children}
    </Button>
  ),
);
FooterButton.displayName = "Popover.FooterButton";

const Popover = Object.assign(PopoverRoot, {
  Trigger,
  Content,
  Divider: PopoverDivider,
  FooterButton,
});

export default Popover;
